-- Port Said Hub | استيراد الأماكن من ملف Port Said Community (شغّله مرة واحدة بعد 01 و02 و05 و09)
-- ملاحظة: الخصم متخزّن في القاعدة بس مخفي من الواجهة لحد ما نفعّل الـ QR. الإحداثيات مؤقتة (مركز بورسعيد) والخريطة بتبحث بالاسم.
SET NAMES utf8mb4;
SELECT t.c, t.n, t.i, t.o FROM (SELECT 'sweets' c,'حلويات' n,'fa-ice-cream' i,4 o UNION ALL SELECT 'shop','تسوق','fa-bag-shopping',5 UNION ALL SELECT 'sport','رياضة','fa-dumbbell',6) t
WHERE NOT EXISTS (SELECT 1 FROM categories x WHERE x.code = t.c);
UPDATE categories SET name_ar='معالم وترفيه', sort_order=1 WHERE code='fun';
UPDATE categories SET sort_order=2 WHERE code='food'; UPDATE categories SET sort_order=3 WHERE code='cafe'; UPDATE categories SET sort_order=7 WHERE code='housing';
UPDATE places SET status='hidden', deleted_at=NOW() WHERE is_demo=1 AND deleted_at IS NULL;
